using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Linq;
class CombatUiChecks {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(Game g,string n){return typeof(Game).GetField(n,F).GetValue(g);}static void Set(Game g,string n,object v){typeof(Game).GetField(n,F).SetValue(g,v);}static object Call(Game g,string n,params object[] a){return typeof(Game).GetMethod(n,F).Invoke(g,a);}static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Pump(){for(int i=0;i<10;i++){Application.DoEvents();System.Threading.Thread.Sleep(10);}}
 [STAThread]static void Main(){try{Run();}catch(Exception ex){while(ex!=null){Console.WriteLine(ex.GetType().Name+": "+ex.Message);ex=ex.InnerException;}Environment.ExitCode=1;}}static void Run(){Application.EnableVisualStyles();using(var game=new Game()){game.Opacity=0;game.Show();var save=new Save();Set(game,"save",save);var run=new RogueRun{id="expedition",seed=0,depth=3,state="combat",pool=new System.Collections.Generic.List<RogueEntry>()};run.partyBattle=PartyCombat.Create(run,save);Call(game,"RenderPartyBattle",run);Call(game,"StopAudio");Pump();var canvas=(PartyBattleCanvas)Get(game,"partyCanvas");Check(canvas.Controls.OfType<HeroSkillButton>().Count()==5,"five icons");Check(canvas.Controls.OfType<HeroSkillButton>().All(b=>b.Art!=null),"all rendered skill art");using(var img=new Bitmap(canvas.Width,canvas.Height)){canvas.DrawToBitmap(img,canvas.ClientRectangle);img.Save("D:/WORK/Cet6Story/.validation/combat-v4-full-ui.png");}Call(game,"RefreshPartySelection",run);Check(Object.ReferenceEquals(canvas,Get(game,"partyCanvas")),"selection reuses canvas");for(int i=0;i<30;i++){var b=run.partyBattle;if(!String.IsNullOrEmpty(b.outcome))break;if(b.phase=="heroes"){var h=b.heroes.First(u=>u.id==b.active);var s=HeroSkills.For(h.id).FirstOrDefault(x=>PartyCombat.CanUse(b,h,x)&&x.Damage>0);if(s==null)PartyCombat.EndHeroes(b);else PartyCombat.BeginSkill(b,b.selectedHero,s.Id,PartyCombat.Targets(b,h,s)[0].id);}else if(b.phase=="attack-question")PartyCombat.AttackAnswer(b,true);else if(b.phase=="defense-question")PartyCombat.DefenseAnswer(b,true);else PartyCombat.Continue(b);Call(game,"RenderPartyBattle",run);Call(game,"StopAudio");Pump();Check(Object.ReferenceEquals(canvas,Get(game,"partyCanvas")),"action canvas stable");}using(var img=new Bitmap(canvas.Width,canvas.Height)){canvas.DrawToBitmap(img,canvas.ClientRectangle);img.Save("D:/WORK/Cet6Story/.validation/combat-v4-full-ui-after.png");}game.Close();Console.WriteLine("PASS full UI: five skill images, three enemy encounter, question/feedback transitions, stable canvas, rendered screenshots");}}
}
